-- ============================================================
-- 水产养殖批次与水质监测管理系统 数据库初始化脚本
-- MySQL 8.0 / utf8mb4 / 库名 new_019
-- 包含建库、建表、索引、字典、角色菜单、6 个月跨度的测试数据
-- 所有图片字段均指向项目内本地文件 uploads/seed/...，无外链
-- 默认账号：admin / admin123（系统管理员），其余账号密码 123456
-- ============================================================
DROP DATABASE IF EXISTS `new_019`;
CREATE DATABASE `new_019` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `new_019`;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;


CREATE TABLE sys_org (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  org_name VARCHAR(64) NOT NULL COMMENT '组织名称',
  org_code VARCHAR(32) NOT NULL COMMENT '组织编码',
  parent_id BIGINT DEFAULT 0 COMMENT '上级组织',
  leader VARCHAR(32) DEFAULT NULL COMMENT '负责人',
  sort INT DEFAULT 0 COMMENT '排序',
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间'
) ENGINE=InnoDB COMMENT='组织（养殖场/片区）';

CREATE TABLE sys_role (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  role_name VARCHAR(64) NOT NULL,
  role_code VARCHAR(32) NOT NULL,
  data_scope VARCHAR(20) NOT NULL DEFAULT 'SELF' COMMENT '数据范围 SELF/DEPT/ORG/ALL',
  remark VARCHAR(200) DEFAULT NULL,
  status TINYINT DEFAULT 1,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uk_role_code (role_code)
) ENGINE=InnoDB COMMENT='角色';

CREATE TABLE sys_user (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  username VARCHAR(50) NOT NULL,
  password VARCHAR(100) NOT NULL COMMENT 'BCrypt',
  real_name VARCHAR(50) NOT NULL,
  avatar VARCHAR(200) DEFAULT NULL,
  phone VARCHAR(20) DEFAULT NULL,
  email VARCHAR(80) DEFAULT NULL,
  org_id BIGINT DEFAULT NULL,
  role_id BIGINT DEFAULT NULL,
  status TINYINT DEFAULT 1,
  login_fail INT DEFAULT 0,
  lock_until DATETIME DEFAULT NULL,
  last_login DATETIME DEFAULT NULL,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  deleted TINYINT DEFAULT 0,
  UNIQUE KEY uk_username (username),
  KEY idx_user_org (org_id)
) ENGINE=InnoDB COMMENT='用户';

CREATE TABLE sys_menu (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  parent_id BIGINT DEFAULT 0,
  menu_name VARCHAR(64) NOT NULL,
  menu_type CHAR(1) NOT NULL COMMENT 'M目录 C菜单 B按钮',
  path VARCHAR(120) DEFAULT NULL,
  perm VARCHAR(80) DEFAULT NULL,
  icon VARCHAR(40) DEFAULT NULL,
  sort INT DEFAULT 0,
  visible TINYINT DEFAULT 1,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB COMMENT='菜单与按钮权限';

CREATE TABLE sys_role_menu (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  role_id BIGINT NOT NULL,
  menu_id BIGINT NOT NULL,
  KEY idx_rm_role (role_id)
) ENGINE=InnoDB COMMENT='角色菜单';

CREATE TABLE sys_dict (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  dict_type VARCHAR(40) NOT NULL,
  dict_code VARCHAR(40) NOT NULL,
  dict_label VARCHAR(60) NOT NULL,
  sort INT DEFAULT 0,
  KEY idx_dict_type (dict_type)
) ENGINE=InnoDB COMMENT='字典';

CREATE TABLE sys_message (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  title VARCHAR(200) NOT NULL,
  content VARCHAR(500) DEFAULT NULL,
  biz_type VARCHAR(20) DEFAULT NULL,
  biz_id BIGINT DEFAULT NULL,
  biz_no VARCHAR(50) DEFAULT NULL,
  receiver_id BIGINT NOT NULL,
  is_read TINYINT DEFAULT 0,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  KEY idx_msg_receiver (receiver_id, is_read)
) ENGINE=InnoDB COMMENT='站内消息';

CREATE TABLE sys_log (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  user_id BIGINT DEFAULT NULL,
  user_name VARCHAR(50) DEFAULT NULL,
  module VARCHAR(40) DEFAULT NULL,
  action VARCHAR(40) DEFAULT NULL,
  biz_no VARCHAR(50) DEFAULT NULL,
  detail VARCHAR(500) DEFAULT NULL,
  ip VARCHAR(40) DEFAULT NULL,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  KEY idx_log_time (create_time)
) ENGINE=InnoDB COMMENT='操作日志';

CREATE TABLE pond (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  pond_no VARCHAR(50) NOT NULL COMMENT '塘口编号',
  pond_name VARCHAR(100) NOT NULL COMMENT '塘口名称',
  area DECIMAL(10,2) NOT NULL COMMENT '面积（亩）',
  depth DECIMAL(6,2) NOT NULL COMMENT '平均水深（米）',
  water_source VARCHAR(30) DEFAULT NULL COMMENT '水源',
  aerator_count INT DEFAULT 0 COMMENT '增氧机台数',
  manager_id BIGINT DEFAULT NULL COMMENT '负责人',
  manager_name VARCHAR(50) DEFAULT NULL,
  status VARCHAR(20) DEFAULT 'NORMAL' COMMENT 'NORMAL/MAINTENANCE/IDLE',
  image VARCHAR(200) DEFAULT NULL COMMENT '现场照片',
  remark VARCHAR(300) DEFAULT NULL,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  deleted TINYINT DEFAULT 0,
  UNIQUE KEY uk_pond_no (pond_no),
  KEY idx_pond_status (status)
) ENGINE=InnoDB COMMENT='塘口档案';

CREATE TABLE breeding_batch (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  batch_no VARCHAR(50) NOT NULL COMMENT '批次编号',
  pond_id BIGINT NOT NULL,
  variety VARCHAR(40) NOT NULL COMMENT '养殖品种',
  seed_source VARCHAR(100) DEFAULT NULL COMMENT '苗种来源',
  stock_date DATE NOT NULL COMMENT '投苗日期',
  stock_qty INT DEFAULT NULL COMMENT '投苗数量（万尾）',
  avg_weight DECIMAL(8,2) DEFAULT NULL COMMENT '平均规格（克/尾）',
  expect_harvest_date DATE DEFAULT NULL COMMENT '预计起捕日',
  target_output DECIMAL(12,2) DEFAULT NULL COMMENT '目标产量（公斤）',
  growth_stage VARCHAR(20) DEFAULT 'FRY' COMMENT 'FRY/JUVENILE/ADULT',
  status VARCHAR(20) DEFAULT 'PREP' COMMENT 'PREP/BREEDING/HARVESTING/CLOSED',
  current_stock DECIMAL(12,2) DEFAULT 0 COMMENT '当前存塘量（公斤）',
  feed_total DECIMAL(12,2) DEFAULT 0 COMMENT '累计投喂量（公斤）',
  manager_id BIGINT DEFAULT NULL,
  manager_name VARCHAR(50) DEFAULT NULL,
  remark VARCHAR(300) DEFAULT NULL,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  deleted TINYINT DEFAULT 0,
  UNIQUE KEY uk_batch_no (batch_no),
  KEY idx_batch_pond (pond_id),
  KEY idx_batch_status (status)
) ENGINE=InnoDB COMMENT='养殖批次（核心主数据）';

CREATE TABLE feeding_plan (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  plan_no VARCHAR(50) NOT NULL,
  batch_id BIGINT NOT NULL,
  feed_name VARCHAR(80) DEFAULT NULL,
  feed_qty DECIMAL(10,2) NOT NULL COMMENT '标准投喂量（公斤）',
  plan_date DATE NOT NULL,
  period VARCHAR(10) DEFAULT 'AM' COMMENT 'AM/NOON/PM',
  executor_id BIGINT DEFAULT NULL,
  executor_name VARCHAR(50) DEFAULT NULL,
  status VARCHAR(20) DEFAULT 'PENDING' COMMENT 'PENDING/DONE/OVERDUE',
  remark VARCHAR(300) DEFAULT NULL,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  deleted TINYINT DEFAULT 0,
  KEY idx_plan_batch (batch_id),
  KEY idx_plan_date (plan_date)
) ENGINE=InnoDB COMMENT='投喂计划';

CREATE TABLE feeding_record (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  plan_id BIGINT NOT NULL,
  batch_id BIGINT NOT NULL,
  feed_qty DECIMAL(10,2) NOT NULL COMMENT '领料量',
  actual_qty DECIMAL(10,2) NOT NULL COMMENT '实际用量',
  execute_time DATETIME NOT NULL,
  operator VARCHAR(50) DEFAULT NULL,
  check_flag TINYINT DEFAULT 0 COMMENT '1 需技术员复核',
  check_note VARCHAR(300) DEFAULT NULL,
  remark VARCHAR(300) DEFAULT NULL,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  KEY idx_fr_batch (batch_id),
  KEY idx_fr_time (execute_time)
) ENGINE=InnoDB COMMENT='投喂执行记录';

CREATE TABLE water_quality (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  record_no VARCHAR(50) NOT NULL,
  pond_id BIGINT NOT NULL,
  batch_id BIGINT NOT NULL,
  check_time DATETIME NOT NULL,
  water_temp DECIMAL(6,2) DEFAULT NULL COMMENT '水温 ℃',
  ph DECIMAL(5,2) DEFAULT NULL,
  dissolved_oxygen DECIMAL(6,2) DEFAULT NULL COMMENT '溶解氧 mg/L',
  ammonia DECIMAL(6,3) DEFAULT NULL COMMENT '氨氮 mg/L',
  nitrite DECIMAL(6,3) DEFAULT NULL COMMENT '亚硝酸盐 mg/L',
  transparency INT DEFAULT NULL COMMENT '透明度 cm',
  tester_id BIGINT DEFAULT NULL,
  tester_name VARCHAR(50) DEFAULT NULL,
  level VARCHAR(20) DEFAULT 'NORMAL' COMMENT 'NORMAL/WARN/DANGER',
  image VARCHAR(200) DEFAULT NULL COMMENT '仪表照片',
  remark VARCHAR(300) DEFAULT NULL,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  deleted TINYINT DEFAULT 0,
  UNIQUE KEY uk_water_no (record_no),
  KEY idx_water_batch (batch_id),
  KEY idx_water_time (check_time)
) ENGINE=InnoDB COMMENT='水质检测记录（核心过程单据）';

CREATE TABLE water_warning (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  warning_no VARCHAR(50) NOT NULL,
  pond_id BIGINT NOT NULL,
  batch_id BIGINT NOT NULL,
  water_id BIGINT DEFAULT NULL,
  warn_type VARCHAR(20) DEFAULT 'MULTI' COMMENT 'DO/PH/NH3/NO2/TEMP/MULTI',
  level VARCHAR(10) DEFAULT 'MID' COMMENT 'LOW/MID/HIGH',
  status VARCHAR(20) DEFAULT 'PENDING' COMMENT 'PENDING/PROCESSING/RETEST/CLOSED',
  content VARCHAR(500) DEFAULT NULL,
  handler_id BIGINT DEFAULT NULL,
  handler_name VARCHAR(50) DEFAULT NULL,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  close_time DATETIME DEFAULT NULL,
  deleted TINYINT DEFAULT 0,
  UNIQUE KEY uk_warn_no (warning_no),
  KEY idx_warn_status (status),
  KEY idx_warn_batch (batch_id)
) ENGINE=InnoDB COMMENT='阈值预警';

CREATE TABLE emergency_record (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  warning_id BIGINT NOT NULL,
  measure VARCHAR(20) NOT NULL COMMENT 'AERATION/WATER_CHANGE/BOTTOM/DISINFECT/RETEST',
  detail VARCHAR(300) DEFAULT NULL,
  operator VARCHAR(50) DEFAULT NULL,
  action_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  retest_result VARCHAR(300) DEFAULT NULL,
  retest_time DATETIME DEFAULT NULL,
  retest_water_id BIGINT DEFAULT NULL,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  KEY idx_em_warning (warning_id)
) ENGINE=InnoDB COMMENT='应急处置与复测';

CREATE TABLE disease_record (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  disease_no VARCHAR(50) NOT NULL,
  batch_id BIGINT NOT NULL,
  pond_id BIGINT NOT NULL,
  symptom VARCHAR(300) NOT NULL,
  death_count INT DEFAULT 0,
  image VARCHAR(200) DEFAULT NULL COMMENT '病害图片',
  report_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  reporter VARCHAR(50) DEFAULT NULL,
  diagnosis VARCHAR(300) DEFAULT NULL,
  drug_name VARCHAR(80) DEFAULT NULL,
  dose VARCHAR(80) DEFAULT NULL,
  withdrawal_days INT DEFAULT NULL COMMENT '休药期天数',
  withdrawal_end DATE DEFAULT NULL COMMENT '休药期截止日',
  review_status VARCHAR(20) DEFAULT 'PENDING' COMMENT 'PENDING/APPROVED/REJECTED/VOID',
  reviewer VARCHAR(50) DEFAULT NULL,
  review_time DATETIME DEFAULT NULL,
  review_note VARCHAR(300) DEFAULT NULL,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  deleted TINYINT DEFAULT 0,
  UNIQUE KEY uk_disease_no (disease_no),
  KEY idx_disease_batch (batch_id)
) ENGINE=InnoDB COMMENT='病害与用药';

CREATE TABLE harvest_record (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  harvest_no VARCHAR(50) NOT NULL,
  batch_id BIGINT NOT NULL,
  pond_id BIGINT NOT NULL,
  plan_date DATE NOT NULL,
  actual_date DATE DEFAULT NULL,
  weight DECIMAL(12,2) NOT NULL COMMENT '起捕重量（公斤）',
  grade VARCHAR(5) DEFAULT 'A',
  destination VARCHAR(80) DEFAULT NULL,
  loss_rate DECIMAL(5,2) DEFAULT 0,
  est_stock DECIMAL(12,2) DEFAULT NULL,
  status VARCHAR(20) DEFAULT 'APPROVED' COMMENT 'APPROVED/DONE/VOID',
  image VARCHAR(200) DEFAULT NULL COMMENT '起捕照片',
  approver VARCHAR(50) DEFAULT NULL,
  remark VARCHAR(300) DEFAULT NULL,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  deleted TINYINT DEFAULT 0,
  UNIQUE KEY uk_harvest_no (harvest_no),
  KEY idx_harvest_batch (batch_id)
) ENGINE=InnoDB COMMENT='起捕记录';

CREATE TABLE transfer_record (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  transfer_no VARCHAR(50) NOT NULL,
  batch_id BIGINT NOT NULL,
  from_pond_id BIGINT NOT NULL,
  to_pond_id BIGINT NOT NULL,
  qty DECIMAL(12,2) NOT NULL COMMENT '转移数量（公斤）',
  transfer_date DATE NOT NULL,
  operator VARCHAR(50) DEFAULT NULL,
  status VARCHAR(20) DEFAULT 'DONE',
  remark VARCHAR(300) DEFAULT NULL,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  KEY idx_transfer_batch (batch_id)
) ENGINE=InnoDB COMMENT='分塘记录';

CREATE TABLE risk_rule (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  rule_name VARCHAR(100) NOT NULL,
  version INT NOT NULL,
  weight_temp DECIMAL(5,2) DEFAULT 20,
  weight_ph DECIMAL(5,2) DEFAULT 15,
  weight_do DECIMAL(5,2) DEFAULT 25,
  weight_ammonia DECIMAL(5,2) DEFAULT 20,
  weight_nitrite DECIMAL(5,2) DEFAULT 15,
  weight_trend DECIMAL(5,2) DEFAULT 5,
  threshold_json JSON DEFAULT NULL,
  enabled TINYINT DEFAULT 1,
  effective_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  create_by VARCHAR(50) DEFAULT NULL,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  KEY idx_rule_version (version)
) ENGINE=InnoDB COMMENT='多参数水质风险分层规则（版本化）';

CREATE TABLE risk_score (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  biz_type VARCHAR(20) DEFAULT 'WATER',
  biz_id BIGINT NOT NULL,
  biz_no VARCHAR(50) DEFAULT NULL,
  rule_version INT DEFAULT 1,
  input_json JSON DEFAULT NULL COMMENT '输入快照',
  score_json JSON DEFAULT NULL COMMENT '逐项得分',
  total_score DECIMAL(6,2) DEFAULT 0,
  risk_level VARCHAR(10) DEFAULT 'LOW',
  advice VARCHAR(600) DEFAULT NULL,
  manual_level VARCHAR(10) DEFAULT NULL,
  manual_reason VARCHAR(300) DEFAULT NULL,
  manual_by VARCHAR(50) DEFAULT NULL,
  manual_time DATETIME DEFAULT NULL,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  KEY idx_score_biz (biz_id),
  KEY idx_score_time (create_time)
) ENGINE=InnoDB COMMENT='风险分层计算留痕';

CREATE TABLE flow_log (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  biz_type VARCHAR(20) NOT NULL,
  biz_id BIGINT NOT NULL,
  biz_no VARCHAR(50) DEFAULT NULL,
  from_status VARCHAR(30) DEFAULT NULL,
  to_status VARCHAR(30) DEFAULT NULL,
  action VARCHAR(60) DEFAULT NULL,
  reason VARCHAR(300) DEFAULT NULL,
  operator_id BIGINT DEFAULT NULL,
  operator_name VARCHAR(50) DEFAULT NULL,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  KEY idx_flow_biz (biz_type, biz_id)
) ENGINE=InnoDB COMMENT='业务时间轴';

CREATE TABLE attachment (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  biz_type VARCHAR(20) NOT NULL,
  biz_id BIGINT NOT NULL,
  file_path VARCHAR(200) NOT NULL,
  file_name VARCHAR(200) DEFAULT NULL,
  file_size BIGINT DEFAULT 0,
  uploader_id BIGINT DEFAULT NULL,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  KEY idx_att_biz (biz_type, biz_id)
) ENGINE=InnoDB COMMENT='附件元数据';

SET FOREIGN_KEY_CHECKS = 1;
-- 完

-- 补充：管理员 / 养殖员 / 仓管员的消息中心数据（覆盖待处置、待复核、库存提醒等场景）
