INSERT INTO sys_message (title, content, biz_type, biz_id, biz_no, receiver_id, is_read, create_time) VALUES
('水质预警 YJ20261031-047 待处置', '批次 YC202609003 溶解氧 2.6 mg/L 低于下限，请安排增氧并 2 小时内复测。', 'WARNING', 47, 'YJ20261031-047', 1, False, '2026-10-31 08:20:00'),
('病害 BH20261018-014 用药待审核', '一号塘批次出现烂鳃症状，技术员已提交恩诺沙星用药方案，请场长复核休药期。', 'DISEASE', 14, 'BH20261018-014', 1, True, '2026-10-18 09:40:00'),
('起捕 QB20261026-006 待审批', '五号塘鲫鱼计划 10-26 起捕 2058 kg，去向商超直供，等待场长审批。', 'HARVEST', 6, 'QB20261026-006', 1, False, '2026-10-26 08:05:00'),
('本月水质合格率下降提醒', '近 30 天水质合格率 60.0%，低于目标 80%，建议排查二号塘与七号塘增氧设备。', 'REPORT', NULL, NULL, 1, False, '2026-10-30 18:00:00'),
('今日投喂任务 3 条待执行', '三号塘、四号塘、六号塘上午投喂计划尚未执行，请在 10:00 前完成并回填实际用量。', 'FEEDING', 1, 'TF20261031-001', 5, False, '2026-10-31 07:30:00'),
('水质录入待办', '七号塘下午需补录一次水质检测（水温、pH、溶氧、氨氮、亚硝酸盐）。', 'WATER', 99, 'SZ20261025-099', 5, True, '2026-10-25 15:00:00'),
('预警 YJ20261004-029 已转处置中', '你上报的预警已由技术员接手，请配合执行换水 1/3 并记录措施。', 'WARNING', 29, 'YJ20261004-029', 5, False, '2026-10-04 17:20:00'),
('饲料库存低于安全线', '淡水鱼配合饲料剩余 1.2 吨，低于安全库存 2 吨，请提交补货申请。', 'STOCK', NULL, NULL, 7, False, '2026-10-29 09:10:00'),
('药品出入库待登记', '10-28 领用的聚维酮碘 12 瓶尚未登记出库，请补录领用人。', 'STOCK', NULL, NULL, 7, True, '2026-10-28 16:40:00'),
('消毒品盘点提醒', '本月消毒品盘点截止 10-31，请完成生石灰、漂白粉账实核对。', 'STOCK', NULL, NULL, 7, False, '2026-10-27 08:00:00');
